SELECT P.POSUUID, D1.propername reportType1, D2.propername reportType2, D3.propername reportType3, D4.propername reportType4, P.PROD_ID prodId, PB.PROD_NAME prodName, PB.IS_FHXGCP isFhxgcp, P.ASSET_CODE assetCode, CASE WHEN P.DETAILNO = 'AMT1_1_1' THEN '现金' WHEN B.SUBJECT_NAME IS NULL THEN ifnull(I.ASSET_NAME,I.ASSET_CODE) ELSE B.SUBJECT_NAME END assetName, P.OLD_ASSET_CODE oldAssetCode, IA.ASSET_NAME oldAssetName, ifnull(I.VDATE, I.PLAN_SDATE) VDATE, ifnull(I.MDATE, I.PLAN_EDATE) MDATE, ifnull(MC.CUSTOMER_NAME, ifnull(mp1.COUNTER_NAME,P.SUBJECT_NAME)) subjectName, ifnull(I.ASSET_YIELD,RATE.ASSET_RATE) RATE, ifnull(P.CCY,'CNY') CCY, AP.POS_AMT delayPayAmt,
P.ASSETVALUE_A costAmt,
AP.TDY_COST_AMT costAmt,
P.ASSETVALUE_B costAmtB,
AP.TDY_COST_AMT costAmtB,
AP.TDY_FLOAT_INGPL floatIngpl, AP.TDY_INTINCEXP INTINCEXP, AP.TDY_INTADJEXP_ADD intadjexpAdd, AP.TDY_LOSS_AMT lossAmt, P.ASSETVALUE_A assetvalueA, P.ASSETVALUE_B assetvalueB, P.INDUSTRY1, P.INDUSTRY2, P.INDUSTRY3, P.INDUSTRY4, ifnull(mp.COUNTER_NAME, p.RIVAL_PARTY) rivalParty, P.PRIVATEPRD_FLAG privateprdFlag, (case D2.propertycode when 'AMT2_1_12' then P.PRIVATEFUND_FLAG end) privatefundFlag, P.MAIN_GRADE mainGrade, P.CREDIT_GRADE creditGrade, P.RATING, P.BONDTOSTOCK_FLAG bondtostockFlag, case when I.ISUNLISTED = '01' then I.ISUNLISTED end as isGovernFund1, I.ORG_ASSET_TYPE1 orgAssetType1, I.ORG_ASSET_TYPE2 orgAssetType2, I.ORG_ASSET_TYPE3 orgAssetType3, P.IS_YHBCGJ isYhbcgj, P.TYPE_FINAL typeFinal, p.is_Fbhy isFbhy, P.pppflag, p.MONIT_TYPE monitType, CASE WHEN AP.MDATE != I.MDATE and I.MDATE is not null THEN AP.MDATE END openplan FROM CHB_MONTH_ASSET_POSITIONDETAIL P LEFT JOIN CHB_ASSET_INFO I ON P.ASSET_CODE = I.ASSET_CODE LEFT JOIN CHB_ASSET_INFO IA ON IA.ASSET_CODE = P.OLD_ASSET_CODE LEFT JOIN BOK_SUBJECT B ON B.BOOKSET_ID = '00000000000000000002' AND B.SUBJECT_NO = P.ASSET_CODE LEFT JOIN CHB_PRD_BASEINFO PB ON P.PROD_ID = PB.PROD_ID AND PB.FPROD_ID IS NULL AND PB.STATUS IN ('E','M') LEFT JOIN MST_CUSTOMER_INFO MC ON MC.CUSTOMER_ID = P.SUBJECT_NAME LEFT JOIN CHB_MST_COUNTER_PARTY MP1 ON MP1.COUNTER_ID = P.SUBJECT_NAME LEFT JOIN CHB_MST_COUNTER_PARTY MP ON MP.COUNTER_ID = P.RIVAL_PARTY LEFT JOIN CHB_REPORT_TEMPLATEDETAIL D4 ON D4.propertycode = P.DETAILNO and D4.proplevel = '4' LEFT JOIN CHB_REPORT_TEMPLATEDETAIL D3 ON D3.propertycode = D4.codeparent and D3.proplevel = '3' LEFT JOIN CHB_REPORT_TEMPLATEDETAIL D2 ON D2.propertycode = D3.codeparent and D2.proplevel = '2' LEFT JOIN CHB_REPORT_TEMPLATEDETAIL D1 ON D1.propertycode = D2.codeparent and D1.proplevel = '1' LEFT JOIN CHB_ASSETS_BASIS_DATA AP ON AP.PROD_ID = P.PROD_ID AND AP.ASSET_ID = P.ASSET_CODE AND AP.VALUE_DATE = case P.TERM when null then STR_TO_DATE('19000101','%Y-%m-%d') else adddate(STR_TO_DATE(P.TERM||'01','%Y-%m-%d'),interval -1 month) end LEFT JOIN (SELECT ASSET_ID,ifnull(ASSET_RATE,0)*100 ASSET_RATE,change_date, row_number() over(partition by ASSET_ID order by change_date desc) rn FROM CHB_ASSET_RATE WHERE asset_rate is not null AND CHANGE_DATE <= adddate(STR_TO_DATE(CONCAT(#{enddate,jdbcType=VARCHAR},'01'),'%Y-%m-%d'),interval 1 month)-1) RATE ON RATE.ASSET_ID = P.ASSET_CODE AND RATE.rn = 1
WHERE P.PROD_ID IS NOT NULL
and P.TERM = #{enddate,jdbcType=VARCHAR}
and P.ASSETVALUE_A is not null and P.ASSETVALUE_A !=0
and P.ASSETVALUE_B is not null and P.ASSETVALUE_B !=0
#{item}
#{item}
