SELECT PRODID prodId,/*产品代码*/ ASSET_CODE assetCode,/*资产代码*/ ACCUAMT assetvalueA,/*剩余金额*/ ACCUAMT assetvalueB,/*剩余金额*/ CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM( SELECT PROD.FINPROD_MARKET_ID PRODID,/*产品代码*/ 'REMAININGCASH' ASSET_CODE,/*资产代码*/ BALANCE.O_AMT ACCUAMT,/*剩余金额*/ BALANCE.O_AMT ACCUQTY,/*剩余本金*/ BALANCE.BALANCE_DATE CDATE,/*生成日*/ BALANCE.O_CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM BOK_BALANCE BALANCE LEFT JOIN BOK_BOOKSET BOOKSET /*投资组合关联账套查询相关信息*/ ON BOOKSET.BOOKSET_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT PROD/*标的类金融产品表*/ ON PROD.FINPROD_MARKET_ID = BALANCE.BOOKSET_ID WHERE 1 =1 AND BALANCE.BALANCE_DATE = #{cdate,jdbcType=DATE} /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' and BOOKSET.ACCT_SUBJECT_TYPE = 'F18'/*取账套表的主体核算类型为F18投资组合*/ and exists (select 1 from FIN_PRODUCT_ADD PRODADD where BALANCE.BOOKSET_ID = PRODADD.PORTFOLIO_ID and prodadd.PROFIT_FLAG = '03')/*只取非保本理财产品 */
#{subjectNo,jdbcType=VARCHAR}
#{prodid,jdbcType=VARCHAR}
UNION ALL SELECT PROD.FINPROD_MARKET_ID PRODID,/*产品代码*/ 'REMAININGCASH' ASSET_CODE,/*资产代码*/ BALANCE.O_AMT ACCUAMT,/*剩余金额*/ BALANCE.O_AMT ACCUQTY,/*剩余本金*/ BALANCE.BALANCE_DATE CDATE,/*生成日*/ BALANCE.O_CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM BOK_BALANCE BALANCE LEFT JOIN BOK_BOOKSET BOOKSET /*投资组合关联账套查询相关信息*/ ON BOOKSET.BOOKSET_ID = BALANCE.BOOKSET_ID LEFT JOIN FIN_PRODUCT PROD/*标的类金融产品表*/ ON PROD.FINPROD_ID = BALANCE.BOOKSET_ID WHERE 1 =1 AND BALANCE.BALANCE_DATE = #{cdate,jdbcType=DATE} /*标的类金融产品.投管分类=理财产品*/ AND PROD.FINPROD_TYPE2 = 'F16' AND BOOKSET.ACCT_SUBJECT_TYPE = 'F16'/*取账套表的主体核算类型为F16净值型产品货币性产品*/ and exists (select 1 from FIN_PRODUCT_ADD PRODADD where BALANCE.BOOKSET_ID = PRODADD.FINPROD_ID and prodadd.PROFIT_FLAG = '03')/*只取非保本理财产品 */
#{subjectNo,jdbcType=VARCHAR}
#{prodid,jdbcType=VARCHAR}
UNION ALL SELECT VAL.PORTFOLIO_ID PRODID,/*产品代码*/ 'REMAININGCASH' ASSET_CODE,/*资产代码*/ val.amount ACCUAMT,/*剩余金额*/ val.amount ACCUQTY,/*剩余本金*/ VAL.CDATE CDATE,/*生成日*/ VAL.CCY CCY /*币种*/ from ptl_cash_position VAL WHERE 1 =1 AND VAL.CDATE = #{cdate,jdbcType=DATE} and exists (select 1 from fin_product_add d where d.portfolio_id = val.portfolio_id and d.profit_flag = '03')/*只取非保本理财产品*/ and val.HODING_TYPE = '03' /*只取实际*/ and VAL.CHL_FINPROD_ID is not null ---只取通道id不为空的数据
#{prodid,jdbcType=VARCHAR}
)

SELECT NULL POSUUID,/*头寸ID:自动生成*/ PRODINFO.PROD_ID prodId,/*产品代码*/ balance.SUBJECT_NO assetCode,/*资产代码*/ BALANCE.O_AMT assetvalueA,/*剩余金额*/ BALANCE.O_AMT assetvalueB,/*剩余本金*/ BALANCE.O_CCY CCY/*币种:关联资产要素信息表CHB_ASSET_INFO得到币种CCY*/ FROM BOK_BALANCE BALANCE LEFT JOIN CHB_PRD_BASEINFO PRODINFO /*产品要素信息*/ on prodinfo.PROD_ID = replace(balance.BOOKSET_ID, 'F16_') WHERE 1 =1 AND DATE_FORMAT(BALANCE.BALANCE_DATE,'%Y-%m-%d') = DATE_FORMAT(#{cdate,jdbcType=DATE},'%Y-%m-%d') and prodinfo.PROFIT_TYPE = '03'/*只取非保本理财产品 */
#{subjectNo,jdbcType=VARCHAR}
#{prodid,jdbcType=VARCHAR}
